                    while st:
                        a,b=st.pop(); cs.append((a,b))
                        for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                            if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==col and (x,y) not in seen:
                                seen.add((x,y)); st.append((x,y))
                    out.append((col,cs))
